require_once __DIR__.'/../includes/auth.php';if(!isAdmin()&&!isTeller()){http_response_code(403);exit('Khusus Admin/Teller.');}require_once __DIR__.'/../includes/pembaruan_helper.php';$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$pesan='';$hasil=[];$mask='';
if($_SERVER['REQUEST_METHOD']==='POST')try{
    layananValidasiToken();$nik=preg_replace('/\D/','',(string)($_POST['nik']??''));$nama=trim(preg_replace('/\s+/u',' ',(string)($_POST['nama_lengkap']??'')));$lahir=trim((string)($_POST['tanggal_lahir']??''));if(strlen($nik)!==16)throw new InvalidArgumentException('Masukkan NIK 16 digit.');if($nama===''||mb_strlen($nama)>160)throw new InvalidArgumentException('Nama lengkap wajib diisi.');$dob=DateTimeImmutable::createFromFormat('!Y-m-d',$lahir);if(!$dob||$dob->format('Y-m-d')!==$lahir)throw new InvalidArgumentException('Tanggal lahir wajib diisi dengan benar.');
    $rate=$db->prepare('SELECT COUNT(*) FROM lookup_internal_audit WHERE user_id=? AND dibuat_pada>=DATE_SUB(NOW(),INTERVAL 15 MINUTE)');$rate->execute([(int)$_SESSION['user_id']]);if((int)$rate->fetchColumn()>=10)throw new RuntimeException('Batas pencarian tercapai. Coba lagi setelah 15 menit.');
    $q=$db->prepare("SELECT id,kode_anggota,nama_lengkap,tanggal_lahir FROM anggota WHERE REPLACE(REPLACE(REPLACE(ktp,' ',''),'-',''),'.','')=? LIMIT 3");$q->execute([$nik]);$calon=$q->fetchAll(PDO::FETCH_ASSOC);$normal=function($s){$s=mb_strtolower(trim(preg_replace('/\s+/u',' ',(string)$s)),'UTF-8');return preg_replace('/[^\p{L}\p{N}]/u','',$s);};$cocok=array_values(array_filter($calon,function($a)use($nama,$lahir,$normal){return $normal($a['nama_lengkap'])===$normal($nama)&&!empty($a['tanggal_lahir'])&&$a['tanggal_lahir']===$lahir;}));$hasil=count($cocok)===1?$cocok:[];$mask='••••••••••••'.substr($nik,-4);$db->prepare('INSERT INTO lookup_internal_audit(user_id,anggota_id,hasil,nik_4_terakhir) VALUES(?,?,?,?)')->execute([(int)$_SESSION['user_id'],$hasil?(int)$hasil[0]['id']:null,$hasil?'cocok':'tidak_cocok',substr($nik,-4)]);
    if(!$hasil)$pesan='Tidak ditemukan kecocokan di data internal koperasi.';
}catch(Throwable $e){$pesan=$e->getMessage();}
