<?php if($pesan):?><div class="alert alert-info"><?=htmlspecialchars($pesan)?></div><?php endif?><form method="post" class="card card-body mb-4" autocomplete="off"><?=layananToken()?><label class="form-label" for="nikInternal">NIK (16 digit)</label><input id="nikInternal" name="nik" inputmode="numeric" pattern="[0-9 .-]{16,24}" maxlength="24" class="form-control mb-3" required autocomplete="off"><label class="form-label" for="namaInternal">Nama lengkap sesuai identitas</label><input id="namaInternal" name="nama_lengkap" maxlength="160" class="form-control mb-3" required autocomplete="off"><label class="form-label" for="lahirInternal">Tanggal lahir</label><input id="lahirInternal" type="date" name="tanggal_lahir" class="form-control mb-3" required><button class="btn btn-primary">Cocokkan data internal</button><small class="text-muted mt-2">Kecocokan mensyaratkan NIK, nama, dan tanggal lahir. Maksimal 10 pencarian per petugas dalam 15 menit. Pencarian dicatat tanpa menyimpan NIK penuh.</small></form>
<?php foreach($hasil as $a):?><section class="card mb-4"><div class="card-header"><h2 class="h5 mb-0">Hasil cocok · NIK <?=htmlspecialchars($mask)?></h2></div><div class="card-body"><p><strong><?=htmlspecialchars($a['nama_lengkap'])?></strong> · <?=htmlspecialchars($a['kode_anggota'])?></p><div class="table-responsive"><table class="table table-striped mb-0"><thead><tr><th>Pinjaman</th><th>Status</th><th>DPD</th><th>KOL</th><th>Sisa pokok</th></tr></thead><tbody><?php
$pins=$db->prepare("SELECT id,kode_pinjaman,status,sisa_pokok FROM pinjaman WHERE anggota_id=? ORDER BY id DESC LIMIT 50");$pins->execute([(int)$a['id']]);foreach($pins->fetchAll(PDO::FETCH_ASSOC) as $p){$aging=hitungDPDPinjaman($db,(int)$p['id']);[$kol]=$aging['dpd']?statusKolektibilitas($aging['dpd']):['KOL 1 - Lancar'];echo '<tr><td>'.htmlspecialchars($p['kode_pinjaman']).'</td><td>'.htmlspecialchars($p['status']).'</td><td>'.(int)$aging['dpd'].'</td><td>'.htmlspecialchars($kol).'</td><td>'.formatRupiah($p['sisa_pokok']).'</td></tr>';}
?></tbody></table></div></div></section><?php endforeach?></div><?php include __DIR__.'/../includes/layout/shell_end.php';?></body></html>
